/** Generates the curriculum seed migration from lib/voice-curriculum (the single source). Run: npx vite-node scripts/generate-curriculum-seed.ts */
import fs from "node:fs";
import { ALL_AREAS, GENERAL_SAFETY } from "../lib/voice-curriculum";

const q = (s: string) => `'${s.replace(/'/g, "''")}'`;
export function buildSeedSql(): string {
  const out: string[] = [
    "-- GENERATED by scripts/generate-curriculum-seed.ts from lib/voice-curriculum. Do not edit by hand; change the source and regenerate.",
    "-- ADDITIVE ONLY and NOT YET APPLIED. Apply after 20261030100000.",
    "-- Seeds the exercise LIBRARY (staff-only until an exercise is assigned; assigning copies a snapshot). Nothing is published or advertised.",
    "-- Skill slugs that already exist (from 20261029110000) are reused, not duplicated. Optional-track skills are inactive so students cannot browse them.",
    ""
  ];
  const skills = new Map<string, { name: string; active: boolean; order: number }>();
  for (const a of ALL_AREAS) if (!skills.has(a.skillSlug)) skills.set(a.skillSlug, { name: a.track ? `${a.title} (optional track)` : a.title, active: !a.track, order: 20 + a.number });
  out.push("insert into dp_voice_skills(slug,name,sort_order,is_active) values");
  out.push([...skills].map(([slug, s]) => ` (${q(slug)},${q(s.name)},${s.order},${s.active})`).join(",\n"));
  out.push("on conflict (slug) do nothing;", "");
  out.push("-- track skills must stay hidden from students even if a slug already existed");
  out.push("update dp_voice_skills set is_active=false where slug like 'track-%';", "");
  out.push("insert into dp_voice_exercises(skill_id,title,instructions,minutes,is_active,visibility,curriculum_key)");
  out.push("select s.id,v.title,v.instructions,v.minutes,true,'assigned_only',v.key from (values");
  const rows: string[] = [];
  for (const a of ALL_AREAS) for (const e of a.exercises) {
    const safety = e.safety ?? GENERAL_SAFETY;
    const text = `${e.student}\n\nCare: ${safety}\n\nRecord in 3–5 minute segments if you submit a recording.`;
    rows.push(` (${q(a.skillSlug)},${q(e.key)},${q(e.title)},${q(text)},${e.minutes})`);
  }
  out.push(rows.join(",\n"));
  out.push(") as v(slug,key,title,instructions,minutes) join dp_voice_skills s on s.slug=v.slug", "on conflict (curriculum_key) do nothing;", "");
  return out.join("\n");
}
if (process.env.WRITE_SEED) {
  fs.writeFileSync("supabase/migrations/20261030110000_dp_voice_curriculum_seed.sql", buildSeedSql());
  console.log("wrote seed");
}
